/// The division PRESCALER code `code` selects, from the PRESCALER_DIV constants above, or 0 for a
/// code none of them names.
#[must_use]
pub const fn prescaler_divisor(code: u32) -> u32 {
    match code {
        0 => 1,
        1 => 2,
        2 => 4,
        3 => 8,
        4 => 16,
        5 => 64,
        6 => 256,
        7 => 1024,
        _ => 0,
    }
}
